/**
 * Stage 20: the identity keyframe model and the Identity Blender recipe's normalisation (plain node, no browser).
 *
 *   node .render-check/run-module.mjs render-identity-keyframes.mjs
 *
 * Three kinds of check:
 *   - PARITY with the backend: the bezier easing against values generated by identity_algebra.bezier_ease in Python,
 *     and the constants (source cap, keyframe cap, default bezier, privacy cosine, modes, curves) read out of
 *     app/roop/identity_algebra.py itself, so a JS mirror cannot drift from the file it mirrors.
 *   - PROPERTIES over random inputs (the failure these functions can have is a boundary one a hand-picked example
 *     never hits): normalisation is idempotent, sorted, one keyframe per frame; edits never duplicate a frame.
 *   - the frame convention: the timeline speaks 1-based UI frames, the recipe 0-based absolute indices.
 */
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
// src/api.js (imported by identityBlend.js for fetchIdentityBlend) reads `window.location` at module scope, so the
// stub goes in BEFORE the dynamic imports; the model under test itself touches no browser API.
globalThis.window = globalThis;
globalThis.location = { protocol: 'http:', host: '127.0.0.1:42003', origin: 'http://127.0.0.1:42003', hash: '' };
globalThis.window.location = globalThis.location;

const {
  CURVES, DEFAULT_BEZIER, MAX_KEYFRAMES, addKeyframe, bezierEase, curvePath, curvePoints, ease, frameIndexOf,
  moveKeyframe, normalizeKeyframes, removeKeyframe, seedWeightsAt, segmentAt, uiFrameOf, updateKeyframe,
} = await import('../src/components/faceswap/identityKeyframes.js');
const {
  BLEND_MODES, DEFAULT_BLEND_MODE, EMPTY_BLEND, MAX_BLEND_SOURCES, PRIVACY_COSINE_DEFAULT, normalizeBlend,
} = await import('../src/components/faceswap/identityBlend.js');

let failures = 0;
const ok = (name, cond, detail = '') => {
  if (cond) { console.log(`  PASS  ${name}`); return; }
  failures += 1;
  console.log(`  FAIL  ${name}${detail ? `\n          ${detail}` : ''}`);
};
const eq = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const near = (a, b, e = 1e-9) => Math.abs(a - b) <= e;

let seed = 0x20c0ffee;
const rnd = () => { seed ^= seed << 13; seed ^= seed >>> 17; seed ^= seed << 5; return ((seed >>> 0) % 1_000_000) / 1_000_000; };
const rint = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));

const here = dirname(fileURLToPath(import.meta.url));
const py = readFileSync(join(here, '..', '..', 'app', 'roop', 'identity_algebra.py'), 'utf8');
const pyConst = (name) => {
  const m = py.match(new RegExp(`^${name}\\s*=\\s*(.+?)\\s*(?:#.*)?$`, 'm'));
  return m ? m[1].trim() : null;
};

// ── parity with identity_algebra.py ─────────────────────────────────────────
console.log('parity with identity_algebra.py');
{
  ok('MAX_BLEND_SOURCES', Number(pyConst('MAX_BLEND_SOURCES')) === MAX_BLEND_SOURCES, `py ${pyConst('MAX_BLEND_SOURCES')} vs js ${MAX_BLEND_SOURCES}`);
  ok('MAX_KEYFRAMES', Number(pyConst('MAX_KEYFRAMES')) === MAX_KEYFRAMES, `py ${pyConst('MAX_KEYFRAMES')} vs js ${MAX_KEYFRAMES}`);
  ok('DEFAULT_PRIVACY_COSINE', Number(pyConst('DEFAULT_PRIVACY_COSINE')) === PRIVACY_COSINE_DEFAULT);
  ok('DEFAULT_BLEND_MODE', pyConst('DEFAULT_BLEND_MODE') === `"${DEFAULT_BLEND_MODE}"`);
  ok('BLEND_MODES', eq(pyConst('BLEND_MODES').replace(/[()"\s]/g, '').split(',').filter(Boolean), [...BLEND_MODES]));
  ok('DEFAULT_BEZIER', eq(pyConst('DEFAULT_BEZIER').replace(/[()\s]/g, '').split(',').map(Number), [...DEFAULT_BEZIER]));
  const declared = py.match(/CURVE_HOLD, CURVE_LINEAR, CURVE_CUBIC_BEZIER = "(\w+)", "(\w+)", "(\w+)"/);
  ok('CURVES (hold, linear, cubic_bezier)', !!declared && eq(declared.slice(1, 4), [...CURVES]));
}

// Generated by identity_algebra.bezier_ease (Python, 60-step bisection), 12 digits.
const GOLDEN = {
  default: { bezier: [0.42, 0.0, 0.58, 1.0], u: [0.0, 0.05, 0.1, 0.25, 0.4, 0.5, 0.6, 0.75, 0.9, 0.95, 1.0],
    y: [0.0, 0.004829749668, 0.019722453548, 0.129161931047, 0.331883870098, 0.5, 0.668116129902, 0.870838068953, 0.980277546452, 0.995170250332, 1.0] },
  custom: { bezier: [0.1, 0.9, 0.9, 0.1], u: [0.0, 0.05, 0.1, 0.25, 0.4, 0.5, 0.6, 0.75, 0.9, 0.95, 1.0],
    y: [0.0, 0.223448380477, 0.321359554345, 0.446822304566, 0.48741851569, 0.5, 0.51258148431, 0.553177695434, 0.678640445655, 0.776551619523, 1.0] },
  clamped: { bezier: [-2.0, -5.0, 4.0, 9.0], u: [0.0, 0.05, 0.1, 0.25, 0.4, 0.5, 0.6, 0.75, 0.9, 0.95, 1.0],
    y: [0.0, 0.05, 0.1, 0.25, 0.4, 0.5, 0.6, 0.75, 0.9, 0.95, 1.0] },
};
console.log('easing');
{
  for (const [name, g] of Object.entries(GOLDEN)) {
    const worst = Math.max(...g.u.map((u, i) => Math.abs(bezierEase(u, ...g.bezier) - g.y[i])));
    ok(`bezier "${name}" matches the Python implementation at ${g.u.length} points`, worst < 1e-10, `worst ${worst}`);
  }
  ok('hold is 0 until the next keyframe, 1 at it', ease('hold', 0.999) === 0 && ease('hold', 1) === 1 && ease('hold', 0) === 0);
  ok('linear is the identity, clipped', ease('linear', 0.37) === 0.37 && ease('linear', 4) === 1 && ease('linear', -1) === 0);
  ok('an unknown curve falls back to linear', ease('wobble', 0.25) === 0.25);
  let mono = true;
  let last = -1;
  for (let i = 0; i <= 200; i++) { const y = bezierEase(i / 200, ...DEFAULT_BEZIER); if (y < last - 1e-12) mono = false; last = y; }
  ok('the default ease-in-out is monotone', mono);
  ok('NaN and out-of-range inputs stay in 0..1', [NaN, -3, 7].every((u) => { const y = bezierEase(u, 0.1, 0.2, 0.3, 0.4); return y >= 0 && y <= 1; }));
}

// ── frame convention ────────────────────────────────────────────────────────
console.log('frame convention');
{
  ok('UI frame 1 is index 0; 60 is 59', frameIndexOf(1) === 0 && frameIndexOf(60) === 59);
  ok('round trip', [1, 2, 99, 12345].every((f) => uiFrameOf({ frame_index: frameIndexOf(f) }) === f));
  ok('a fractional UI frame rounds like the timeline does', frameIndexOf(10.4) === 9 && frameIndexOf(10.6) === 10);
}

// ── normalisation ───────────────────────────────────────────────────────────
console.log('normalizeKeyframes');
{
  const out = normalizeKeyframes([
    { frame_index: 90, weights: { a: 0, b: 100 }, curve: 'hold' },
    { frame_index: 10.4, weights: { a: 100, b: 0 }, curve: 'WOBBLE', bezier: [9, -4, 2, 7] },
    { frame_index: 90, weights: { a: 30, b: 70 } },                      // the later one wins
    { frame_index: -3, weights: { a: 1 } },
    { frame_index: 60, weights: { a: 0, b: 0 } },                        // says nothing
    'junk', null, { frame_index: NaN, weights: { a: 1 } },
  ]);
  ok('sorted, deduped (later wins), junk dropped', eq(out.map((k) => k.frame_index), [10, 90]));
  ok('an unknown curve becomes linear; bezier clamped to 0..1', out[0].curve === 'linear' && eq(out[0].bezier, [1, 0, 1, 1]));
  ok('the later duplicate replaced the earlier one whole', eq(out[1].weights, { a: 30, b: 70 }) && out[1].curve === 'linear');
  ok('weights for a source that is not in the blender are KEPT (the backend ignores them)',
    eq(normalizeKeyframes([{ frame_index: 1, weights: { a: 5, ghost: 9 } }])[0].weights, { a: 5, ghost: 9 }));
  ok('capped at MAX_KEYFRAMES', normalizeKeyframes(Array.from({ length: MAX_KEYFRAMES + 30 }, (_, i) => ({ frame_index: i, weights: { a: 1 } }))).length === MAX_KEYFRAMES);
  ok('null / non-array input is an empty list', eq(normalizeKeyframes(null), []) && eq(normalizeKeyframes('x'), []));

  let bad = 0;
  for (let t = 0; t < 400; t++) {
    const list = Array.from({ length: rint(0, 20) }, () => ({
      frame_index: rint(-5, 300), curve: ['hold', 'linear', 'cubic_bezier', 'x'][rint(0, 3)],
      bezier: [rnd() * 3 - 1, rnd() * 3 - 1, rnd() * 3 - 1, rnd() * 3 - 1],
      weights: { a: rnd() * 150 - 20, b: rnd() < 0.3 ? 0 : rnd() * 100 },
    }));
    const n1 = normalizeKeyframes(list);
    const frames = n1.map((k) => k.frame_index);
    const sorted = frames.every((f, i) => i === 0 || f > frames[i - 1]);
    const clean = n1.every((k) => k.frame_index >= 0 && CURVES.includes(k.curve) && k.bezier.every((x) => x >= 0 && x <= 1)
      && Object.values(k.weights).every((w) => w >= 0 && w <= 100) && Object.values(k.weights).some((w) => w > 0));
    if (!sorted || !clean || !eq(normalizeKeyframes(n1), n1)) bad++;
  }
  ok('random lists: sorted, unique, clean and idempotent (400 random)', bad === 0, `${bad} violations`);
}

// ── edits ───────────────────────────────────────────────────────────────────
console.log('edits');
{
  const comps = [{ source_id: 'a', weight: 50 }, { source_id: 'b', weight: 50 }];
  let list = [];
  let r = addKeyframe(list, 11, { a: 100, b: 0 }, 300);
  ok('add stores the BACKEND index (UI 11 -> 10)', r.created && r.frame_index === 10 && r.list[0].frame_index === 10);
  list = r.list;
  ok('adding on an occupied frame does not duplicate', (() => { const o = addKeyframe(list, 11, { a: 1 }, 300); return !o.created && o.list === list; })());
  r = addKeyframe(list, 400, { a: 0, b: 100 }, 300);
  ok('a frame past the clip is clamped to its last frame', r.list[r.list.length - 1].frame_index === 299);
  ok('the cap refuses a 65th keyframe',
    (() => { const full = normalizeKeyframes(Array.from({ length: MAX_KEYFRAMES }, (_, i) => ({ frame_index: i, weights: { a: 1 } })));
      const o = addKeyframe(full, 200, { a: 1 }, 300); return !o.created && o.full === true && o.list === full; })());
  list = r.list;
  ok('move: frame 10 -> UI 50', eq(moveKeyframe(list, 10, 50, 300).map((k) => k.frame_index), [49, 299]));
  ok('move onto an occupied frame is refused (same list)', moveKeyframe(list, 10, 300, 300) === list);
  ok('move outside the clip is refused', moveKeyframe(list, 10, 0, 300) === list && moveKeyframe(list, 10, 301, 300) === list);
  ok('move to where it already is is a no-op', moveKeyframe(list, 10, 11, 300) === list);
  ok('remove', eq(removeKeyframe(list, 10).map((k) => k.frame_index), [299]));
  const upd = updateKeyframe(list, 10, { curve: 'cubic_bezier', bezier: [0.2, 0.3, 0.4, 0.5], weights: { b: 25 } });
  ok('update merges weights and sets curve + bezier', upd[0].curve === 'cubic_bezier' && eq(upd[0].bezier, [0.2, 0.3, 0.4, 0.5])
    && upd[0].weights.a === 100 && upd[0].weights.b === 25);
  ok('update that zeroes every weight drops the keyframe', updateKeyframe(list, 10, { weights: { a: 0, b: 0 } }).length === 1);

  let uniq = 0;
  for (let t = 0; t < 300; t++) {
    let l = [];
    for (let i = 0; i < 25; i++) {
      const op = rint(0, 2);
      if (op === 0) l = addKeyframe(l, rint(1, 120), { a: 1 + rnd() * 99, b: rnd() * 50 }, 120).list;
      else if (op === 1 && l.length) l = moveKeyframe(l, l[rint(0, l.length - 1)].frame_index, rint(1, 120), 120);
      else if (l.length) l = removeKeyframe(l, l[rint(0, l.length - 1)].frame_index);
    }
    const f = l.map((k) => k.frame_index);
    if (new Set(f).size !== f.length || !f.every((x, i) => i === 0 || x > f[i - 1]) || f.some((x) => x < 0 || x > 119)) uniq++;
  }
  ok('random add / move / remove sequences never duplicate, unsort or leave the clip (300 x 25 ops)', uniq === 0, `${uniq} bad`);

  // seeding a new keyframe at the playhead must not change what the track already shows
  const track = normalizeKeyframes([{ frame_index: 0, weights: { a: 100, b: 0 } }, { frame_index: 99, weights: { a: 0, b: 100 }, curve: 'linear' }]);
  const mid = seedWeightsAt(track, comps, 50);
  ok('seed at a keyframe is that keyframe\'s shares', eq(seedWeightsAt(track, comps, 1), { a: 100, b: 0 }) && eq(seedWeightsAt(track, comps, 100), { a: 0, b: 100 }));
  ok('seed halfway along a linear segment is an even mix, summing to 100', near(mid.a, 50.0, 0.6) && near(mid.a + mid.b, 100, 1e-9), JSON.stringify(mid));
  ok('seed on an empty track is the blender\'s own weights (normalised)', eq(seedWeightsAt([], [{ source_id: 'a', weight: 30 }, { source_id: 'b', weight: 10 }], 5), { a: 75, b: 25 }));
  const hold = normalizeKeyframes([{ frame_index: 0, weights: { a: 100 }, curve: 'hold' }, { frame_index: 99, weights: { b: 100 } }]);
  ok('seed inside a hold segment is the held keyframe', eq(seedWeightsAt(hold, comps, 60), { a: 100, b: 0 }));
  ok('segmentAt before / after the track clamps to the ends', segmentAt(track, 1).s === 0 && segmentAt(track, 100).next === null && segmentAt([], 5) === null);
}

// ── drawing ─────────────────────────────────────────────────────────────────
console.log('curve glyphs');
{
  ok('hold is a step, linear the diagonal', eq(curvePoints('hold'), [[0, 0], [1, 0], [1, 1]]) && eq(curvePoints('linear'), [[0, 0], [1, 1]]));
  const p = curvePath('cubic_bezier', DEFAULT_BEZIER, 100, 30, 6);
  ok('a bezier path starts bottom-left and ends top-right of its padded box', p.startsWith('M6.00,24.00') && p.endsWith('L94.00,6.00'), p);
  ok('hold path is M..L..L', /^M[\d.,]+ L[\d.,]+ L[\d.,]+$/.test(curvePath('hold', DEFAULT_BEZIER, 100, 30, 6)));
}

// ── the recipe ──────────────────────────────────────────────────────────────
console.log('normalizeBlend');
{
  const e = normalizeBlend(null);
  ok('empty recipe carries the Stage 20 fields', e.mode === 'slerp' && eq(e.keyframes, []) && e.deidentify.enabled === false
    && e.deidentify.max_cosine === PRIVACY_COSINE_DEFAULT && eq(e.dials, { jawline: 0 }));
  ok('EMPTY_BLEND is what normalising nothing gives', eq(normalizeBlend(EMPTY_BLEND), e));
  const r = normalizeBlend({
    enabled: 1, mode: 'LINEAR', components: [{ source_id: 'a', weight: 1 }], dials: { age: 9, jawline: 7 }, min_cosine: 'x',
    keyframes: [{ frame_index: 5, weights: { a: 1 } }],
    deidentify: { enabled: true, references: ['x', 'x', '', 'y', 'z', 'w', 'v', 'u'], max_cosine: 7, min_primary_cosine: -1 },
  });
  ok('mode is a known value or the default (an unknown one is the default; "LINEAR" is not normalised: the server does that)',
    r.mode === 'slerp' && normalizeBlend({ mode: 'linear' }).mode === 'linear');
  ok('removed dials are dropped, the offered one clamped', eq(r.dials, { jawline: 1 }));
  ok('de-identification: unique references capped at five, thresholds clamped',
    eq(r.deidentify.references, ['x', 'y', 'z', 'w', 'v']) && r.deidentify.max_cosine === 0.95 && r.deidentify.min_primary_cosine === 0);
  ok('keyframes are normalised', r.keyframes.length === 1 && r.keyframes[0].curve === 'linear');
  ok('idempotent and JSON-safe', eq(normalizeBlend(r), r) && eq(JSON.parse(JSON.stringify(r)), r));
  ok('a panel edit of one field keeps the keyframes', eq(normalizeBlend({ ...r, enabled: true }).keyframes, r.keyframes));
}

console.log(failures === 0 ? '\nall identity keyframe checks passed' : `\n${failures} identity keyframe check(s) FAILED`);
globalThis.__RENDER_CHECK_FAILURES__ = failures;
